+        successful_output("    bFalse [1]\n")
+    );
+    assert_eq!(
+        eval(r#"print! "a\{"b"}c\{"d \{" e\{"f"}g\{-2+3}"}"}""#),
+        successful_output("abcd  efg1\n")
